fn nanquantile(mut a: Vec<i8>, q: i8) -> i8 {
    // Handle edge cases first
    if q == 0 {
        return get_min_val(&a);
    }
    if q == 100 {
        return get_max_val(&a);
    }
    
    // Sort the array
    a.sort();
    
    // Calculate the index for the quantile
    // Formula: index = (q/100) * (n-1)
    let n = a.len() as f64;
    let q_fraction = q as f64 / 100.0;
    let index = q_fraction * (n - 1.0);
    
    // Get the lower and upper indices
    let lower_idx = index.floor() as usize;
    let upper_idx = index.ceil() as usize;
    
    // If lower and upper indices are the same, return that element
    if lower_idx == upper_idx {
        return a[lower_idx];
    }
    
    // Otherwise, interpolate between the two values
    let lower_val = a[lower_idx] as f64;
    let upper_val = a[upper_idx] as f64;
    let weight = index - lower_idx as f64;
    
    let result = lower_val + weight * (upper_val - lower_val);
    
    // Round to nearest integer (i8)
    result.round() as i8
}